"""Prepare blank browser-only consent/intake; no collection, upload or solicitation."""
from common11 import *
HTML='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Furniture AI — future creator intake</title>
<style>body{font:17px system-ui;max-width:900px;margin:2rem auto;padding:1rem;line-height:1.6}label{display:block;margin:1rem 0}input[type=text],input[type=date],textarea,select{width:100%;padding:.5rem;box-sizing:border-box}button{padding:.8rem}aside{background:#fff2cc;padding:1rem}fieldset{margin:1rem 0}</style>
<h1>Future modern-room photograph intake</h1><aside>This is a blank preparation tool. No photographs are uploaded or requested. Exported metadata is unverified; it does not approve images, annotations, training or evaluation. Keep personal permission evidence private.</aside>
<h2>Plain-language permission</h2><p>I created, own, or am authorized to grant permission for the listed photographs. I give Furniture AI nonexclusive, royalty-free permission to store them, make annotations and modified copies, and use them for the agreed model-training or evaluation purpose. I permit distribution of resulting models and use in a future commercial application. This does not by itself authorize public redistribution of my original photographs. My credit preferences and any conditions are recorded below. Other people's privacy and third-party rights must be resolved separately.</p>
<form id="intake"><label>Photograph IDs (one per line; no files)<textarea name="photos" required></textarea></label><label>Creator identifier or private pseudonym<input type="text" name="creator" required></label><label>Source/capture group ID<input type="text" name="source" required></label><label>Opaque physical room/location IDs (one per line; no street address)<textarea name="rooms" required></textarea></label><label>Source / attribution preference<textarea name="credit"></textarea></label><label>Private permission-evidence reference (do not paste signatures or contact details into public Git)<input type="text" name="evidence" required></label><label>Permission date<input type="date" name="date" required></label><label>Proposed purpose, before any model use<select name="purpose" required><option value="">Choose explicitly</option value="training">Training only</option><option value="independent_evaluation">Independent evaluation only</option></select></label>
<fieldset><legend>Explicit creator permission — all start unconfirmed</legend><label><input type="checkbox" name="storage" required> Storage of the listed photographs</label><label><input type="checkbox" name="annotation_and_modification" required> Annotation and modified copies</label><label><input type="checkbox" name="model_training_or_evaluation" required> Model use for the selected purpose</label><label><input type="checkbox" name="commercial_model_distribution" required> Distribution of derived models and commercial application use</label><label><input type="checkbox" name="privacy" required> Privacy, other people, private material and third-party rights have been addressed</label><label><input type="checkbox" name="confirm" required> I explicitly confirm this grant and my authority; the evidence reference is genuine</label></fieldset>
<button type="submit">Export unverified intake metadata</button><p id="status" aria-live="polite"></p></form>
<h2>Photograph guidance for later collection</h2><p>Use diverse living rooms, offices, bedrooms and dining/kitchen spaces with furniture, plants, televisions and ordinary clutter. Avoid identifiable people unless documented permission covers the intended use. Remove documents, addresses, screens containing private information and location metadata before submission where appropriate; retain an internal hash trail for any modified copies. Never photograph a private room without authorization.</p>
<h2>Separate groups and annotation</h2><p>All photographs of the same physical room, capture session, photographer or known source group stay in one purpose. Similar/reuploaded scenes need duplicate checks. Do not publish precise addresses. Independent evaluation must exclude training and previously exposed sources.</p><p>Later review can display proposed boxes/masks for accept/edit/ignore decisions, avoiding manual coordinate entry. Proposals remain inactive until evidence checks pass. For every image review Sofa, Chair, Table, Bed, Desk, Cabinet and Lamp, including unannotated instances, occlusion, truncation and category completeness. Chair includes seating stools and bar stools; footstools, ottomans and step stools remain separate. Cabinet fronts, built-ins, desks/tables and ceiling fixtures require semantic decisions. Missing annotations are never verified negatives.</p>
<script>document.querySelector('#intake').addEventListener('submit',event=>{event.preventDefault();const f=event.currentTarget;if(!f.reportValidity())return;const d=new FormData(f),lines=k=>d.get(k).split(/\\r?\\n/).map(s=>s.trim()).filter(Boolean);const record={schema:'future-modern-room-intake-v1',photo_ids:lines('photos'),creator_id:d.get('creator').trim(),source_group_id:d.get('source').trim(),room_group_ids:lines('rooms'),credit:d.get('credit'),permission_evidence:d.get('evidence'),permission_date:d.get('date'),purpose:d.get('purpose'),scopes:Object.fromEntries(['storage','annotation_and_modification','model_training_or_evaluation','commercial_model_distribution'].map(k=>[k,d.get(k)==='on'])),privacy_and_third_party_rights_resolved:d.get('privacy')==='on',explicit_confirmation:d.get('confirm')==='on',status:'submitted_unverified',human_reviewed:false,annotations_active:false,photograph_download_authorized:false};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)+'\\n'],{type:'application/json'}));a.href=url;a.download='creator-intake-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#status').textContent='Exported locally. Evidence, source identity, duplicates and group assignment still require verification.';});</script></html>'''
def run():
    atomic(OUT/'creator-intake.html',HTML.encode())
    emit(REPORT/'modern-room-intake-workflow.json',dict(workflow_only=True,photos_obtained_or_third_parties_contacted=0,interface='creator-intake.html',
      permission_template='Local browser page; no boxes prechecked or reviews fabricated',privacy_guidance_present=True,
      creator_source_room_capture_groups_required=True,precise_addresses_required=False,
      proposed_masks_remain_inactive=True,complete_annotation_checklist=['Sofa','Chair','Table','Bed','Desk','Cabinet','Lamp'],
      split_policy='Fix photographer/source/physical-room groups before model use; independent evaluation separate from training and exposed development',
      future_duplicate_checks=['source IDs/URLs','original and modified SHA256 trail','perceptual duplicates/crops','room and creator aliases'],
      optional_annotation_UI='Later proposed-box/mask overlays with accept/edit/ignore controls; no manual coordinate entry required. Not a model annotator or training approval.',
      no_original_photo_redistribution_grant_assumed=True))
if __name__=='__main__':run()
